import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.DrDMl0tG.js";const p=JSON.parse('{"title":"Changelog: v2.6.1","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.6.1.md","filePath":"sections/changelog/v2.6.1.md"}'),n={name:"sections/changelog/v2.6.1.md"};function s(i,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog-v2-6-1" tabindex="-1">Changelog: v2.6.1 <a class="header-anchor" href="#changelog-v2-6-1" aria-label="Permalink to &quot;Changelog: v2.6.1&quot;">​</a></h1><p>This page covers 2.6.0 and the 2.6.1 patch release that followed it. The binary package includes matching RaiSim and rayrai headers, libraries and CMake exports. Rebuild applications and Python extensions after updating: headers copied over an older package can compile against incompatible object layouts.</p><h2 id="tendons" tabindex="-1">Tendons <a class="header-anchor" href="#tendons" aria-label="Permalink to &quot;Tendons&quot;">​</a></h2><ul><li><code>raisim::Tendon</code> routes a cable through attachment sites, pulleys and wrapping surfaces on single bodies, articulated systems and granular particles. The tendon system solves the length constraints each step. See <a href="./../Tendons.html">Tendons</a>.</li><li>World XML files load and save tendons. Worlds that used the older wire elements are migrated when they are loaded.</li><li><code>RayraiWindow</code> and the TCP viewer draw each tendon route as instanced cylinders that follow the physics route, width, colour and enabled state.</li></ul><h2 id="tcp-viewer" tabindex="-1">TCP viewer <a class="header-anchor" href="#tcp-viewer" aria-label="Permalink to &quot;TCP viewer&quot;">​</a></h2><p>The viewer and its server protocol grew considerably; <a href="./../RayraiTcpViewer.html">Rayrai TCP Viewer</a> describes each feature.</p><ul><li><strong>Split panes.</strong> Each pane is a full viewer session with its own connection, camera and panels. The layout is saved.</li><li><strong>Local world simulation.</strong> Drop a world XML onto a pane, or pass <code>--simulate world.xml</code>, to run the world in a child process that the pane connects to.</li><li><strong>Recording.</strong><ul><li>MP4 recording through <code>ffmpeg</code>.</li><li>PNG sequences with <strong>Encode To Video</strong>.</li><li>Session record and replay.</li><li>Server-requested screenshots and videos (<code>RaisimServer::requestSaveScreenshot</code>, <code>startRecordingVideo</code>).</li></ul></li><li><strong>Live Signals.</strong> A channel picker, pinned objects and CSV export.</li><li><strong>Scene editing.</strong> Spawn and delete objects, export the world, and pull bodies with a spring by Ctrl/Cmd-dragging.</li><li><strong>Settings.</strong> A settings file, <code>$HOME/.rayrai/settings.yaml</code>, stores the layout and preferences. The left panel uses seven icon tabs.</li><li><strong>API rename.</strong> The custom-client request struct was renamed from <code>SimControlRequest</code> to <code>tcp_viewer::ClientRequest</code>. There is no alias. Force commands sent through it are multiplied by the target body&#39;s mass on the server.</li><li><strong>Server port and request handling.</strong><ul><li>When the requested port is taken, <code>RaisimServer::launchServer</code> binds the next free port and warns; <code>getPort()</code> reports the actual port.</li><li>A malformed client request closes the connection.</li></ul></li></ul><h2 id="_2-6-1" tabindex="-1">2.6.1 <a class="header-anchor" href="#_2-6-1" aria-label="Permalink to &quot;2.6.1&quot;">​</a></h2><ul><li>Panes restored from a saved layout reconnect to their saved server.</li><li>Pane dividers no longer draw over popup menus or take their clicks.</li><li>Windows installer fixes.</li></ul>',9)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
